-- NexaFlow accounting workflow tables; idempotent bootstrap.

CREATE TABLE IF NOT EXISTS accounting_documents (id CHAR(32) PRIMARY KEY, owner_id CHAR(32) NOT NULL, client_id CHAR(32) NOT NULL, period_key VARCHAR(20) NOT NULL, doc_type VARCHAR(80) NOT NULL, name VARCHAR(190) NOT NULL, stored_name VARCHAR(64) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes INT UNSIGNED NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'received', archived TINYINT(1) NOT NULL DEFAULT 0, version INT UNSIGNED NOT NULL DEFAULT 1, previous_id CHAR(32) NULL, comment VARCHAR(1000) NULL, uploaded_by CHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_acc_docs (owner_id,client_id,period_key,archived), KEY idx_acc_doc_versions(previous_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_document_audit (id CHAR(32) PRIMARY KEY, owner_id CHAR(32) NOT NULL, document_id CHAR(32) NOT NULL, user_id CHAR(32) NOT NULL, action VARCHAR(24) NOT NULL, details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_acc_doc_audit(document_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_period_closures(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,period_key VARCHAR(20) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'open',checklist JSON NOT NULL,comment TEXT NULL,closed_by CHAR(32) NULL,closed_at DATETIME NULL,updated_by CHAR(32) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_acc_close(owner_id,client_id,period_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_bank_imports(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,file_hash CHAR(64) NOT NULL,filename VARCHAR(190) NOT NULL,imported_by CHAR(32) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bank_file(owner_id,file_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_bank_transactions(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,import_id CHAR(32) NOT NULL,transaction_key CHAR(64) NOT NULL,operation_date DATE NOT NULL,amount DECIMAL(14,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'UAH',direction VARCHAR(8) NOT NULL,counterparty VARCHAR(190) NULL,account_number VARCHAR(80) NULL,purpose TEXT NULL,reference VARCHAR(190) NULL,match_status VARCHAR(20) NOT NULL DEFAULT 'unmatched',client_id CHAR(32) NULL,invoice_id CHAR(32) NULL,document_id CHAR(32) NULL,matched_by CHAR(32) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bank_tx(owner_id,transaction_key),KEY idx_bank_match(owner_id,match_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_bank_match_history(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,transaction_id CHAR(32) NOT NULL,user_id CHAR(32) NOT NULL,action VARCHAR(20) NOT NULL,old_client_id CHAR(32) NULL,new_client_id CHAR(32) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_bank_history(transaction_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

  CREATE TABLE IF NOT EXISTS accounting_service_invoices(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,invoice_no VARCHAR(64) NOT NULL,issued_on DATE NOT NULL,due_on DATE NOT NULL,period_key VARCHAR(20) NOT NULL,items JSON NOT NULL,total DECIMAL(14,2) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'draft',issuer_snapshot JSON NULL,created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_acc_invoice(owner_id,invoice_no),KEY idx_acc_invoice_client(owner_id,client_id,period_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_service_payments(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,invoice_id CHAR(32) NOT NULL,amount DECIMAL(14,2) NOT NULL,paid_on DATE NOT NULL,bank_transaction_id CHAR(32) NULL,reversed_at DATETIME NULL,reversed_by CHAR(32) NULL,reverse_reason VARCHAR(1000) NULL,created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_acc_payment_invoice(invoice_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_period_history(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,period_key VARCHAR(20) NOT NULL,old_status VARCHAR(24) NOT NULL,new_status VARCHAR(24) NOT NULL,comment TEXT NULL,user_id CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_acc_period_history(owner_id,client_id,period_key,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_client_portal_access(owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,user_id CHAR(32) NOT NULL,granted_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(owner_id,client_id,user_id),KEY idx_portal_user(user_id,owner_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_client_requests(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,period_key VARCHAR(20) NOT NULL,title VARCHAR(190) NOT NULL,due_on DATE NULL,status VARCHAR(24) NOT NULL DEFAULT 'waiting',created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_portal_requests(owner_id,client_id,period_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_client_responses(id CHAR(32) PRIMARY KEY,request_id CHAR(32) NOT NULL,user_id CHAR(32) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_portal_responses(request_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_payment_notices(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,invoice_id CHAR(32) NOT NULL,user_id CHAR(32) NOT NULL,amount DECIMAL(14,2) NOT NULL,comment VARCHAR(1000) NULL,proof_document_id CHAR(32) NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_payment_notices(owner_id,client_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accounting_finance_history(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,entity_type VARCHAR(24) NOT NULL,entity_id CHAR(32) NOT NULL,action VARCHAR(24) NOT NULL,amount DECIMAL(14,2) NULL,user_id CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_acc_finance_history(owner_id,client_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
